insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('b7ff2df406', 'strony', 'Który znacznik HTML służy do tworzenia nagłówka najwyższego stopnia?', '["<h1>","<head>","<header>","<h6>"]'::jsonb, 0, '<h1> to najważniejszy nagłówek, <h6> najmniej ważny. <head> to sekcja metadanych dokumentu.', 'original', NULL, false, false, '[]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('861b250966', 'strony', 'Atrybut alt w znaczniku <img> określa', '["tekst alternatywny wyświetlany, gdy obraz się nie wczyta","wysokość obrazu","adres pliku graficznego","podpis pod obrazem widoczny zawsze"]'::jsonb, 0, 'alt opisuje obraz dla czytników ekranu i jest pokazywany, gdy grafika się nie załaduje.', 'original', NULL, false, false, '[]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('b2df5708b4', 'strony', 'Aby połączyć dwie komórki tabeli w poziomie, należy użyć atrybutu', '["colspan=\"2\"","rowspan=\"2\"","merge=\"2\"","span=\"row\""]'::jsonb, 0, 'colspan łączy kolumny (poziomo), rowspan łączy wiersze (pionowo).', 'original', NULL, false, false, '[]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('06f5845db2', 'strony', 'Aby połączyć dwie komórki tabeli w pionie, należy użyć atrybutu', '["rowspan=\"2\"","colspan=\"2\"","valign=\"2\"","height=\"2\""]'::jsonb, 0, 'rowspan rozciąga komórkę na kilka wierszy.', 'original', NULL, false, false, '[]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('d858d7c2f7', 'strony', 'Który znacznik tworzy listę numerowaną?', '["<ol>","<ul>","<dl>","<li>"]'::jsonb, 0, 'ol = ordered list. ul to lista punktowana, li to pojedynczy element listy.', 'original', NULL, false, false, '[]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c480efc3d4', 'strony', 'Link otwierający stronę w nowej karcie wymaga atrybutu', '["target=\"_blank\"","target=\"_self\"","rel=\"new\"","href=\"_new\""]'::jsonb, 0, '_blank otwiera nowe okno lub kartę, _self (domyślnie) tę samą.', 'original', NULL, false, false, '[]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('93dd59b7ee', 'strony', 'Który zapis tworzy odnośnik do kotwicy o id „kontakt” na tej samej stronie?', '["<a href=\"#kontakt\">","<a href=\"kontakt\">","<a name=\"#kontakt\">","<a id=\"kontakt\">"]'::jsonb, 0, 'Znak # w href wskazuje element o danym id w bieżącym dokumencie.', 'original', NULL, false, false, '[]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('a9effd9575', 'strony', 'Element formularza, który pozwala wybrać jedną opcję z rozwijanej listy, to', '["<select>","<input type=\"checkbox\">","<textarea>","<fieldset>"]'::jsonb, 0, '<select> z elementami <option> tworzy listę rozwijaną.', 'original', NULL, false, false, '[]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('d8ea886380', 'strony', 'Pola typu radio należą do jednej grupy, gdy mają ten sam atrybut', '["name","id","value","class"]'::jsonb, 0, 'Przeglądarka grupuje przyciski radio po wspólnej wartości name: można zaznaczyć tylko jeden z grupy.', 'original', NULL, false, false, '[]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('a048cdf2d7', 'strony', 'Kliknięcie etykiety ustawia kursor w polu tekstowym, jeżeli', '["atrybut for etykiety jest równy id pola","atrybut name etykiety jest równy name pola","etykieta ma klasę pola","pole ma atrybut label"]'::jsonb, 0, '<label for="x"> jest powiązany z elementem o id="x".', 'original', NULL, false, false, '[]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('3dbb41fd35', 'strony', 'Metoda formularza, która przesyła dane widoczne w pasku adresu, to', '["GET","POST","PUT","SEND"]'::jsonb, 0, 'GET dokleja dane do URL jako query string; POST wysyła je w treści żądania.', 'original', NULL, false, false, '[]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('d19c05d778', 'strony', 'Znacznik <br> służy do', '["przejścia do nowej linii","pogrubienia tekstu","wstawienia poziomej linii","utworzenia akapitu"]'::jsonb, 0, '<br> to łamanie linii. Pozioma linia to <hr>, akapit to <p>.', 'original', NULL, false, false, '[]'::jsonb);
