insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c6853739a9f79', 'bazy', 'Baza danych zawiera tabelę uczniowie z polami: imie, nazwisko, klasa. Aby odnaleźć imiona i nazwiska tych uczniów, których nazwiska rozpoczynają się literą M, należy zastosować polecenie SQL', '["SELECT nazwisko, imie FROM uczniowie WHERE nazwisko IN ''M%'';","SELECT nazwisko, imie FROM uczniowie WHERE nazwisko LIKE ''M%'';","SELECT nazwisko, imie FROM uczniowie ORDER BY nazwisko = ''M%'';","SELECT nazwisko, imie FROM uczniowie ORDER BY nazwisko IN ''M%'';"]'::jsonb, 1, NULL, 'cke', NULL, false, true, '["E.14 wrzesien 2015"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c2abf98d754c0', 'bazy', 'Baza danych zawiera tabelę artykuly z polami: nazwa, typ, producent, cena. Aby wyświetlić wszystkie nazwy artykułów wyłącznie typu pralka, dla których cena jest z przedziału 1 000 PLN i 1 500 PLN, należy zastosować polecenie', '["SELECT nazwa FROM artykuly WHERE typ=''pralka'' AND cena FROM 1000 TO 1500;","SELECT nazwa FROM artykuly WHERE typ=''pralka'' OR cena BETWEEN 1000 OR 1500;","SELECT nazwa FROM artykuly WHERE typ=''pralka'' OR cena BETWEEN 1000 AND 1500;","SELECT nazwa FROM artykuly WHERE typ=''pralka'' AND cena BETWEEN 1000 AND 1500;"]'::jsonb, 3, NULL, 'cke', NULL, false, true, '["E.14 wrzesien 2015"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('ce06a237aa1f9', 'bazy', 'Wartość pola tabeli pełniącego rolę klucza podstawowego', '["musi być unikalna.","jest zawsze typu numerycznego.","służy do szyfrowania zawartości tabeli.","może przyjmować wartość pustą (NULL)."]'::jsonb, 0, NULL, 'cke', NULL, false, true, '["E.14 wrzesien 2015"]'::jsonb);
