insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c3a4afad3ed41', 'bazy', 'Baza danych 6-letniej szkoły podstawowej zawiera tabelę szkola z polami: imie, nazwisko, klasa. Wszyscy uczniowie klas 1-5 zdali do następnej klasy. Aby zwiększyć wartość w polu klasa o 1 należy użyć polecenia', '["SELECT szkola FROM klasa = klasa + 1 WHERE klasa >= 1 AND klasa <= 5;","SELECT nazwisko, imie FROM klasa = klasa + 1 WHERE klasa > 1 OR klasa < 5;","UPDATE szkola SET klasa = klasa + 1 WHERE klasa >= 1 AND klasa <= 5;","UPDATE nazwisko, imie SET klasa = klasa + 1 WHERE klasa > 1 OR klasa < 5;"]'::jsonb, 2, NULL, 'cke', NULL, false, true, '["E.14 wrzesien 2015"]'::jsonb);
