insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c222a517cd091', 'bazy', 'W bazie danych hurtowni zdefiniowano tabelę sprzedaz o polach: id, kontrahent, grupa_cenowa, obrot. Aby wyszukać wyłącznie kontrahentów z drugiej grupy cenowej, których obrót jest większy niż 4000 zł, należy zastosować polecenie', '["SELECT sprzedaz FROM kontrahent WHERE obrot > 4000;","SELECT kontrahent FROM sprzedaz WHERE grupa_cenowa = 2 OR obrot > 4000;","SELECT kontrahent FROM sprzedaz WHERE grupa_cenowa = 2 AND obrot > 4000;","SELECT sprzedaz FROM kontrahent WHERE grupa_cenowa = 2 AND obrot > 4000;"]'::jsonb, 2, NULL, 'cke', NULL, false, true, '["E.14 pazdziernik 2016"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cae8c12e46226', 'bazy', 'Dana jest tabela programisci o polach: id, nick, ilosc_kodu, ocena. Pole ilosc_kodu zawiera liczbę linii kodu napisanych przez programistę w danym miesiącu. Aby policzyć sumę linii kodu, który napisali wszyscy programiści, należy użyć polecenia', '["SELECT SUM(ocena) FROM ilosc_kodu;","SELECT SUM(ilosc_kodu) FROM programisci;","SELECT COUNT(programisci) FROM ilosc_kodu;","SELECT MAX(ilosc_kodu) FROM programisci;"]'::jsonb, 1, NULL, 'cke', NULL, false, true, '["E.14 pazdziernik 2016"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c7e63830a1149', 'bazy', 'W instrukcji CREATE TABLE użycie klauzuli PRIMARY KEY przy deklaracji pola tabeli spowoduje, że pole to stanie się', '["kluczem obcym.","indeksem klucza.","indeksem unikalnym.","kluczem podstawowym."]'::jsonb, 3, NULL, 'cke', NULL, false, true, '["E.14 pazdziernik 2016"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c5b4f43146cb5', 'bazy', 'Baza danych księgarni zawiera tabelę książki z polami: id, idAutor, tytul, ileSprzedanych oraz tabelę autorzy z polami: id, imie, nazwisko. Aby stworzyć raport sprzedanych książek z tytułami i nazwiskami autorów, należy', '["stworzyć kwerendę wyszukującą tytuły książek.","zdefiniować relację 1..n dla tabel książki i autorzy, a następnie stworzyć kwerendę łączącą obie tabele.","zdefiniować relację 1..1 dla tabel książki i autorzy, a następnie stworzyć kwerendę łączącą obie tabele.","stworzyć dwie osobne kwerendy: pierwszą wyszukującą tytuły książek, drugą wyszukującą nazwiska autorów."]'::jsonb, 1, NULL, 'cke', NULL, false, true, '["E.14 pazdziernik 2016"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cc50b0bb938ac', 'bazy', 'Istnieje tabela pracownicy z polami: id, imie, nazwisko, pensja. W nowym roku postanowiono podnieść pensję wszystkim pracownikom o 100 zł. Aktualizacja ta w bazie danych będzie miała postać', '["UPDATE pracownicy SET pensja = pensja + 100;","UPDATE pracownicy SET pensja = 100;","UPDATE pensja SET +100;","UPDATE pensja SET 100;"]'::jsonb, 0, NULL, 'cke', NULL, false, true, '["E.14 pazdziernik 2016"]'::jsonb);
