insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c238fbf6fce06', 'aplikacje', 'W instrukcji warunkowej języka JavaScript należy sprawdzić przypadek, gdy zmienne a oraz b są dodatnie, z czego zmienna b jest mniejsza od 100. Warunek taki powinien być zapisany w następujący sposób:', '["if (a > 0 || b > 0 || b > 100) ...","if (a > 0 && b > 0 || b > 100) ...","if (a > 0 || (b > 0 && b < 100)) ...","if (a > 0 && b > 0 && b < 100) ..."]'::jsonb, 3, NULL, 'cke', NULL, false, true, '["E.14 pazdziernik 2016"]'::jsonb);
