insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c07bed1105bf4', 'bazy', 'Zdefiniowano bazę danych z tabelą sklepy o polach: nazwa, ulica, miasto, branza. Aby wyszukać wszystkie nazwy sklepów spożywczych zlokalizowanych wyłącznie we Wrocławiu, należy posłużyć się kwerendą:', '["SELECT sklepy FROM nazwa WHERE branza=''spożywczy'' BETWEEN miasto=''Wrocław'';","SELECT sklepy FROM branza=''spożywczy'' WHERE miasto=''Wrocław'';","SELECT nazwa FROM sklepy WHERE branza=''spożywczy'' OR miasto=''Wrocław'';","SELECT nazwa FROM sklepy WHERE branza=''spożywczy'' AND miasto=''Wrocław'';"]'::jsonb, 3, NULL, 'cke', NULL, false, true, '["E.14 styczen 2016"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c8363c87855e9', 'bazy', 'Zdefiniowano bazę danych z tabelą podzespoly o polach: model, producent, typ, cena. Aby wyświetlić wszystkie modele pamięci RAM firmy Kingston w kolejności od najtańszej do najdroższej, należy posłużyć się kwerendą:', '["SELECT model FROM podzespoly WHERE typ=''RAM'' AND producent=''Kingston'' ORDER BY cena ASC;","SELECT model FROM podzespoly WHERE typ=''RAM'' AND producent=''Kingston'' ORDER BY cena DESC;","SELECT model FROM podzespoly WHERE typ=''RAM'' OR producent=''Kingston'' ORDER BY cena DESC;","SELECT model FROM producent WHERE typ=''RAM'' OR producent=''Kingston'' ORDER BY podzespoly ASC;"]'::jsonb, 0, NULL, 'cke', NULL, false, true, '["E.14 styczen 2016"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cdb780e91b282', 'bazy', 'W celu przyśpieszenia operacji na bazie danych należy dla pól często wyszukiwanych lub sortowanych', '["utworzyć indeks.","dodać klucz obcy.","dodać więzy integralności.","stworzyć osobną tabelę przechowującą tylko te pola."]'::jsonb, 0, NULL, 'cke', NULL, false, true, '["E.14 styczen 2016"]'::jsonb);
