insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c6edb01e3702a', 'bazy', 'Zdefiniowano bazę danych z tabelą mieszkancy o polach: nazwisko, imie, miasto. Następnie stworzono następujące zapytanie do bazy:', '["SELECT nazwisko, imie FROM mieszkancy AS ''Poznań'' OR ''Kraków'';","SELECT nazwisko, imie FROM mieszkancy WHERE miasto HAVING ''Poznań'' OR ''Kraków'';","SELECT nazwisko, imie FROM mieszkancy WHERE miasto=''Poznań'' OR miasto=''Kraków'';","SELECT nazwisko, imie FROM mieszkancy WHERE miasto BETWEEN ''Poznań'' OR ''Kraków'';"]'::jsonb, 2, NULL, 'cke', NULL, false, true, '["E.14 styczen 2016"]'::jsonb);
