insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c0bace629a668', 'bazy', 'Dana jest tabela ksiazki z polami: tytul, autor (typu tekstowego), cena (typu liczbowego). Aby kwerenda SELECT zwróciła tylko tytuły, dla których cena jest mniejsza od 50 zł, należy zapisać:', '["SELECT * FROM ksiazki WHERE cena < 50;","SELECT tytul FROM ksiazki WHERE cena < 50;","SELECT tytul FROM ksiazki WHERE cena > ''50 zł'';","SELECT ksiazki FROM tytul WHERE cena < ''50 zł'';"]'::jsonb, 1, NULL, 'cke', NULL, false, true, '["E.14 styczen 2017"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c4442a484d0ea', 'bazy', 'W bazie danych MySQL dana jest tabela programów komputerowych o polach: nazwa, producent, rokWydania. Aby kwerenda SELECT zwróciła wszystkie nazwy producentów tak, by nazwy te nie powtarzały się, należy zapisać:', '["SELECT UNIQUE producent FROM programy;","SELECT DISTINCT producent FROM programy;","SELECT producent FROM programy WHERE UNIQUE;","SELECT producent FROM programy WHERE producent NOT DUPLICATE;"]'::jsonb, 1, NULL, 'cke', NULL, false, true, '["E.14 styczen 2017"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('ca84bea6375aa', 'bazy', 'Tabela filmy zawiera klucz główny id oraz klucz obcy rezyserID. Tabela rezyserzy zawiera klucz główny id. Obydwie tabele połączone są relacją jeden po stronie reżyserzy do wielu po stronie filmy. Aby w kwerendzie SELECT połączyć tabele filmy i reżyserzy, należy zapisać', '["... filmy JOIN rezyserzy ON filmy.id = rezyserzy.id ...","... filmy JOIN rezyserzy ON filmy.id = rezyserzy.filmyID ...","... filmy JOIN rezyserzy ON filmy.rezyserID = rezyserzy.id ...","... filmy JOIN rezyserzy ON filmy.rezyserID = rezyserzy.filmyID ..."]'::jsonb, 2, NULL, 'cke', NULL, false, true, '["E.14 styczen 2017"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c838816ed6498', 'bazy', 'Na rysunku przedstawiono dwie tabele: Klienci (ID, imie, nazwisko, telefon) oraz Zamowienia (ID, data). Aby połączyć je relacją jeden do wielu, jeden po stronie Klienci, wiele po stronie Zamowienia, należy', '["połączyć relacją pola ID z obu tabel.","dodać pole klucza obcego do tabeli Zamowienia i połączyć je z ID tabeli Klienci.","dodać pole klucza obcego do tabeli Klienci i połączyć je z ID tabeli Zamowienia.","zdefiniować trzecią tabelę z dwoma kluczami obcymi. Jeden klucz połączyć z ID tabeli Klienci, drugi klucz połączyć z ID tabeli Zamowienia."]'::jsonb, 1, NULL, 'cke', NULL, false, true, '["E.14 styczen 2017"]'::jsonb);
