insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cae5ac7a19ca1', 'bazy', 'W tabeli podzespoly należy zmienić wartość pola URL na ''toshiba.pl'' dla wszystkich rekordów, gdzie pole producent to TOSHIBA. W języku SQL modyfikacja ta będzie miała postać:', '["UPDATE podzespoly SET URL = ''toshiba.pl'';","UPDATE producent = ''TOSHIBA'' SET URL = ''toshiba.pl'';","UPDATE podzespoly.producent = ''TOSHIBA'' SET URL = ''toshiba.pl'';","UPDATE podzespoly SET URL = ''toshiba.pl'' WHERE producent = ''TOSHIBA'';"]'::jsonb, 3, NULL, 'cke', NULL, false, true, '["E.14 styczen 2017"]'::jsonb);
