insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('caad0f62ace93', 'strony', 'Przedstawiono efekt formatowania CSS (pierwsza litera akapitu jest duża i niebieska) oraz kod HTML. Jak należy zdefiniować styl, aby osiągnąć takie formatowanie?', '["#first-letter { font-size: 400%; color: blue; }",".first-letter { font-size: 400%; color: blue; }","p::first-letter { font-size: 400%; color: blue; }","p.first-letter { font-size: 400%; color: blue; }"]'::jsonb, 2, NULL, 'cke', '/q/caad0f62ace93-f.webp', false, false, '["E.14 czerwiec 2022","E.14 styczen 2024","E.14 styczen 2025"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cab2829c6eb74', 'strony', '<style> td {padding: 30px; } </style> … <td style="padding: 10px;">Anna</td> <td>Ewa</td> Przedstawione formatowanie CSS, przy założeniu, że żadne inne formatowanie nie jest zdefiniowane, sprawi, że', '["marginesy wewnętrzne wszystkich komórek będą wynosiły 30 px","marginesy wewnętrzne wszystkich komórek będą wynosiły 10 px","margines wewnętrzny komórki z napisem Anna będzie miał 10 px, a z napisem Ewa – 30 px","margines wewnętrzny komórki z napisem Anna będzie miał 30 px, a z napisem Ewa – 10 px"]'::jsonb, 2, NULL, 'cke', NULL, false, false, '["E.14 czerwiec 2022","E.14 styczen 2024","E.14 styczen 2025"]'::jsonb);
