insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cbb1611a75f3b', 'bazy', 'SELECT nazwa, NIP FROM firmy WHERE obrot < 4000; Dana jest tabela firmy zawierająca następujące kolumny: nazwa, adres, NIP, obrot (obrót w ostatnim miesiącu), rozliczenie, status. Wykonanie kwerendy SQL SELECT sprawi, że zostaną wyświetlone', '["wszystkie dane firm, które w ostatnim miesiącu miały obrót co najmniej 4000 zł.","wszystkie dane firm, które w ostatnim miesiącu miały obrót mniejszy niż 4000 zł.","jedynie nazwa oraz numer NIP firm, które w ostatnim miesiącu miały obrót co najmniej 4000 zł.","jedynie nazwa oraz numer NIP firm, które w ostatnim miesiącu miały obrót mniejszy niż 4000 zł."]'::jsonb, 3, NULL, 'cke', NULL, false, false, '["E.14 czerwiec 2022","E.14 styczen 2024","E.14 styczen 2025"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cb4e5bbe06663', 'bazy', 'Dana jest tabela pracownicy, do której wpisano rekordy przedstawione obok. Po uruchomieniu podanej w ramce kwerendy SQL zostanie wyświetlona wartość', '["1300","2200","2600","5400"]'::jsonb, 2, NULL, 'cke', '/q/cb4e5bbe06663-f.webp', false, false, '["E.14 czerwiec 2022","E.14 styczen 2024","E.14 styczen 2025"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c7fb97f92e709', 'bazy', 'Aby prawidłowo utworzyć relację typu m…n nienarażoną na redundancję danych, należy', '["stworzyć tabelę pomocniczą.","posortować przynajmniej jedną z tabel.","połączyć bezpośrednio klucze obce obu tabel.","połączyć bezpośrednio klucze podstawowe obu tabel."]'::jsonb, 0, NULL, 'cke', NULL, false, false, '["E.14 czerwiec 2022","E.14 styczen 2024","E.14 styczen 2025"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('ccd9c1e6c19fa', 'kompetencje', 'Zgodnie z właściwościami ACID dotyczącymi wykonywania transakcji wymaganie izolacji (ang. isolation) oznacza, że', '["po wykonaniu transakcji system bazy danych będzie spójny.","pod pewnymi warunkami dane zmieniane przez transakcję mogą zostać wycofane.","w przypadku konfliktu z inną transakcją, obie modyfikują te same dane w tym samym czasie.","jeżeli dwie transakcje wykonują się współbieżnie, to zwykle nie widzą wprowadzanych przez siebie zmian."]'::jsonb, 3, NULL, 'cke', NULL, false, false, '["E.14 czerwiec 2022","E.14 styczen 2024","E.14 styczen 2025"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c13214dcb2879', 'bazy', 'Baza danych zawiera tabelę ksiazki o polach: tytul, id_autora, data_wypoz, id_czytelnika. Każdego dnia generowany jest raport książek wypożyczonych danego dnia. Wyświetlane są jedynie tytuły książek. Która z kwerend SQL posłuży do stworzenia tego raportu?', '["SELECT * FROM ksiazki;","SELECT tytul FROM ksiazki;","SELECT tytul FROM ksiazki WHERE data_wypoz = CURRENT_DATE();","SELECT tytul, data_wypoz FROM ksiazki WHERE data_wypoz = CURRDATENT_E();"]'::jsonb, 2, NULL, 'cke', NULL, false, false, '["E.14 czerwiec 2022","E.14 styczen 2024","E.14 styczen 2025"]'::jsonb);
