insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c47b2379a02d2', 'angielski', 'W języku PHP należy zapisać warunek, który będzie spełniony, gdy zmienna $a będzie dowolną liczbą całkowitą mniejszą od -10 lub gdy zmienna $b będzie dowolną liczbą z przedziału (25, 75). Wyrażenie logiczne użyte w tym warunku ma postać', '["($a < -10) or (($b > 25) or ($b < 75))","($a < -10) or (($b > 25) and ($b < 75))","($a < -10) and (($b > 25) or ($b < 75))","($a < -10) and (($b > 25) and ($b < 75))"]'::jsonb, 1, NULL, 'cke', NULL, false, false, '["E.14 czerwiec 2022","E.14 styczen 2024","E.14 styczen 2025"]'::jsonb);
