insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('ccd33075d3dfd', 'aplikacje', 'Która z wymienionych zasad nie wpłynie korzystnie na zwiększenie czytelności kodu?', '["Nazwy zmiennych powinny odzwierciedlać ich zadanie.","Kod powinien być napisany bez wcięć i zbędnych enterów.","W każdej linii kodu powinna występować tylko jedna instrukcja.","Należy wprowadzać komentarze w trudniejszych częściach kodu."]'::jsonb, 1, NULL, 'cke', NULL, false, false, '["E.14 czerwiec 2022","E.14 styczen 2024","E.14 styczen 2025"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cf826824f487e', 'aplikacje', 'W języku JavaScript wynik działania instrukcji zmienna1 –= 1; będzie taki sam, jak instrukcji', '["zmienna1––;","zmienna1++;","zmienia1 = zmienna1 - 0;","zmienna1 === zmienna1 - 1;"]'::jsonb, 0, NULL, 'cke', NULL, false, false, '["E.14 czerwiec 2022","E.14 styczen 2024","E.14 styczen 2025"]'::jsonb);
