insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cdf80f7e56c26', 'aplikacje', 'W języku JavaScript stworzono funkcję o nazwie licz_pitagoras, która oblicza długość przeciwprostokątnej trójkąta prostokątnego, zgodnie z twierdzeniem Pitagorasa. Funkcja pobiera dwa parametry wejściowe i zwraca wartość. Prawidłowe wywołanie takiej funkcji, wraz z pobraniem zwróconego wyniku, będzie miało postać', '["licz_pitagoras(a, b);","licz_pitagoras(a, b, c);","c = licz_pitagoras(a, b);","licz_pitagoras(a, b) = c;"]'::jsonb, 2, NULL, 'cke', NULL, false, false, '["E.14 czerwiec 2022","E.14 styczen 2024","E.14 styczen 2025"]'::jsonb);
