insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cd60886544566', 'aplikacje', 'W kodzie HTML zdefiniowano formularz, który wysyła dane do pliku formularz.php. Po wciśnięciu przycisku typu submit przeglądarka przechodzi do przedstawionego adresu. …/formularz.php?imie=Anna&nazwisko=Kowalska Na podstawie podanego adresu można powiedzieć, że dane do pliku formularz.php zostały przesłane metodą', '["GET","POST","COOKIE","SESSION"]'::jsonb, 0, NULL, 'cke', NULL, false, false, '["E.14 czerwiec 2022","E.14 styczen 2024","E.14 styczen 2025"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cff23f904855f', 'bazy', 'Które z zadań programistycznych może być wykonane tylko po stronie klienta przeglądarki?', '["Sprawdzanie danych wpisywanych do pola tekstowego w czasie rzeczywistym.","Sprawdzenie hasła użytkownika w bazie danych powiązanej z aplikacją internetową.","Zapisanie danych pobranych z formularza w bazie danych powiązanej z aplikacją internetową.","Bezpieczne wyświetlenie personalizowanej zawartości strony ze względu na prawa użytkownika aplikacji."]'::jsonb, 0, NULL, 'cke', NULL, false, false, '["E.14 czerwiec 2022","E.14 styczen 2024"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cd02c801d5da1', 'aplikacje', 'function tekst() { var h = location.hostname; document.getElementById("info").innerHTML = h; } Przedstawiona funkcja, zapisana językiem JavaScript, ma za zadanie', '["umożliwić przejście do wskazanej lokalizacji hosta.","wyświetlić w elemencie o id = \"info\" adres hosta wskazany pierwszym odnośnikiem.","wyświetlić w elemencie o id = \"info\" nazwę hosta, z którego pochodzi wyświetlona strona.","wyświetlić na przycisku lokalizację hosta, a po jego wciśnięciu umożliwić przejście do wskazanej lokalizacji."]'::jsonb, 2, NULL, 'cke', NULL, false, false, '["E.14 czerwiec 2022","E.14 styczen 2024","E.14 styczen 2025"]'::jsonb);
