insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c27f541f8ef98', 'angielski', 'Program zapisany w języku PHP ma za zadanie obliczyć średnią pozytywnych ocen ucznia od 2 do 6. Warunek wybierania ocen w pętli liczącej średnią powinien zawierać wyrażenie logiczne', '["$ocena > 2 or $ocena < 6","$ocena > 2 and $ocena < 6","$ocena >= 2 or $ocena <= 6","$ocena >= 2 and $ocena <= 6"]'::jsonb, 3, NULL, 'cke', NULL, false, false, '["EE.09 czerwiec 2021"]'::jsonb);
