insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c0c4f3a145063', 'bazy', 'Tabele: Klienci (id, imie, nazwisko, poziom) i Zgloszenia (id, Klienci_id FK, opis) są powiązane relacją jeden do wielu. Aby wybrać jedynie opis zgłoszenia oraz odpowiadające mu nazwisko klienta dla zgłoszenia numer 5, należy wydać polecenie', '["SELECT opis, nazwisko FROM Zgloszenia JOIN Klienci WHERE Klienci.id = 5;","SELECT opis, nazwisko FROM Zgloszenia JOIN Klienci ON Klienci.id = Zgloszenia.id WHERE Zgloszenia.id = 5;","SELECT opis, nazwisko FROM Zgloszenia JOIN Klienci ON Klienci.id = Zgloszenia.Klienci_id WHERE Klienci.id = 5;","SELECT opis, nazwisko FROM Zgloszenia JOIN Klienci ON Klienci.id = Zgloszenia.Klienci_id WHERE Zgloszenia.id = 5;"]'::jsonb, 3, NULL, 'cke', NULL, false, false, '["EE.09 czerwiec 2021"]'::jsonb);
