insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cf27d823e3d95', 'bazy', 'W bazie danych sklepu istnieją dwie tabele powiązane relacją: produkty oraz oceny. Tabela oceny zawiera dowolną liczbę ocen klientów dla danego produktu opisaną polami: id, ocena (pole numeryczne), produktID (klucz obcy). Aby wskazać maksymalną ocenę dla produktu o ID równym 10, należy posłużyć się zapytaniem', '["MAX SELECT ocena FROM oceny WHERE produktID = 10;","SELECT MAX(ocena) FROM oceny WHERE produktID = 10;","COUNT MAX SELECT ocena FROM oceny WHERE produktID = 10;","SELECT MAX COUNT(ocena) FROM oceny WHERE produktID = 10;"]'::jsonb, 1, NULL, 'cke', NULL, false, false, '["EE.09 styczen 2021"]'::jsonb);
