insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c327f6d1b5b55', 'aplikacje', 'Instrukcją równoważną funkcjonalnie do przedstawionej instrukcji JavaScript jest', '["if(dzialanie == 1) wynik = a + b;\nelse if(dzialanie == 2) wynik = a - b;\nelse if(dzialanie == 3) wynik = a * b;\nelse wynik = a / b;","if(dzialanie == 1) wynik = a + b;\nelse if(dzialanie == 2) wynik = a - b;\nelse if(dzialanie == 3) wynik = a * b;\nelse if(dzialanie == 4) wynik = a / b;","if(dzialanie != 1) wynik = a + b;\nif(dzialanie != 2) wynik = a - b;\nif(dzialanie != 3) wynik = a * b;\nif(dzialanie != 4) wynik = a / b;","if(dzialanie = 1) wynik = a + b;\nelse if(dzialanie = 2) wynik = a - b;\nelse if(dzialanie = 3) wynik = a * b;\nelse if(dzialanie = 4) wynik = a / b;"]'::jsonb, 1, NULL, 'cke', NULL, false, false, '["EE.09 czerwiec 2022"]'::jsonb);
