insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cea6d994faa67', 'podstawy', 'W tabeli mieszkancy z polami id, imie, nazwisko, ulica, numer, czynsz (wartość całkowita) należy wybrać dane osób mieszkających na ulicy Mickiewicza pod numerami 71, 72, 80, których czynsz jest niższy niż 1000 zł. Klauzula WHERE do zapytania będzie miała postać', '["WHERE ulica = ''Mickiewicza'' OR numer IN (71, 72, 80) OR czynsz < 1000","WHERE ulica = ''Mickiewicza'' AND numer IN (71, 72, 80) OR czynsz < 1000","WHERE ulica = ''Mickiewicza'' AND numer IN (71, 72, 80) AND czynsz < 1000","WHERE ulica = ''Mickiewicza'' AND numer > 70 AND numer < 81 OR czynsz < 1000"]'::jsonb, 2, NULL, 'cke', NULL, false, false, '["EE.09 czerwiec 2022"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c5f7bd47c52a4', 'bazy', 'Wskaż kwerendę, która z tabeli klienci wybierze jedynie nazwiska trzech najlepszych klientów, czyli takich, którzy na swoim koncie mają najwięcej punktów (pole całkowite punkty).', '["SELECT nazwisko FROM klienci LIMIT 3;","SELECT nazwisko FROM klienci ORDER BY punkty DESC LIMIT 3;","SELECT nazwisko FROM klienci ORDER BY nazwisko DESC LIMIT 3;","SELECT LIMIT 3 nazwisko FROM klienci ORDER BY nazwisko DESC;"]'::jsonb, 1, NULL, 'cke', NULL, false, false, '["EE.09 czerwiec 2022"]'::jsonb);
