insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c28c620080b16', 'bazy', 'Tabele: Firmy (id, nazwa, poziom) i Zamowienia (id, Firmy_id FK, uwagi) są powiązane relacją jeden do wielu. Aby wybrać jedynie id zamówienia wraz z odpowiadającą mu nazwą firmy dla firm, których poziom jest równy 4, należy zastosować polecenie', '["SELECT Zamowienia.id, nazwa FROM Zamowienia JOIN Firmy WHERE poziom = 4;","SELECT id, nazwa FROM Zamowienia JOIN Firmy ON Zamowienia.Firmy_id = Firmy.id WHERE poziom = 4;","SELECT Zamowienia.id, nazwa FROM Zamowienia JOIN Firmy ON Zamowienia.id = Firmy.id WHERE poziom = 4;","SELECT Zamowienia.id, nazwa FROM Zamowienia JOIN Firmy ON Zamowienia.Firmy_id = Firmy.id WHERE poziom = 4;"]'::jsonb, 3, NULL, 'cke', NULL, false, false, '["EE.09 styczen 2022"]'::jsonb);
