insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cb030812e3b92', 'bazy', 'Tabele: Studenci (id, imie, nazwisko, grupa), Zapisy (idStudenta, idZajecia), Zajecia (id, nazwa, wykladowca) są powiązane relacją. Aby wybrać jedynie nazwiska studentów oraz odpowiadające im idZajecia dla studentów z grupy 15, należy wydać kwerendę', '["SELECT nazwisko, idZajecia FROM Studenci INNER JOIN Zapisy WHERE grupa= 15;","SELECT nazwisko, idZajecia FROM Studenci INNER JOIN Zapisy ON Studenci.id = Zapisy.idStudenta;","SELECT nazwisko, idZajecia FROM Studenci JOIN Zapisy ON Studenci.id = Zapisy.idZajecia WHERE grupa = 15;","SELECT nazwisko, idZajecia FROM Studenci JOIN Zapisy ON Studenci.id = Zapisy.idStudenta WHERE grupa = 15;"]'::jsonb, 3, NULL, 'cke', NULL, false, false, '["EE.09 czerwiec 2023","EE.09 czerwiec 2024","EE.09 czerwiec 2025","EE.09 czerwiec 2026"]'::jsonb);
