insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c2365414c7c45', 'strony', 'Na obrazie przedstawiono projekt układu bloków witryny: w pierwszym rzędzie BLOK 1 i BLOK 2, w drugim BLOK 3 (wąski) i BLOK 4 (szeroki), na dole BLOK 5 na całą szerokość. Zakładając, że bloki są realizowane za pomocą znaczników sekcji, ich formatowanie w CSS, oprócz ustawionych szerokości dla bloków: 1, 2, 3, 4 (blok 5 nie ma ustawionej szerokości), powinno zawierać właściwość', '["float: left dla wszystkich bloków.","clear: both dla wszystkich bloków.","clear: both dla bloku 5 oraz float: left jedynie dla 1 i 2 bloku.","clear: both dla bloku 5 oraz float: left dla pozostałych bloków."]'::jsonb, 3, NULL, 'cke', NULL, false, false, '["EE.09 czerwiec 2023","EE.09 czerwiec 2024","EE.09 czerwiec 2025","EE.09 czerwiec 2026"]'::jsonb);
