insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('ce1d29e201ec1', 'bazy', 'W bazie danych sklepu internetowego, w tabeli klienci znajdują się między innymi pola całkowite: punkty, liczbaZakupow oraz pole ostatnieZakupy typu DATE. Klauzula WHERE do kwerendy wybierającej dane klientów, którzy mają więcej niż 3000 punktów albo wykonali zakupy więcej niż 100 razy, a ostatnie zakupy wykonali co najmniej w roku 2022 ma postać', '["WHERE punkty > 3000 OR liczbaZakupow > 100 OR ostatnieZakupy >= ''2022-01-01''","WHERE punkty > 3000 AND liczbaZakupow > 100 OR ostatnieZakupy >= ''2022-01-01''","WHERE (punkty > 3000 OR liczbaZakupow > 100) AND ostatnieZakupy >= ''2022-01''","WHERE punkty > 3000 AND liczbaZakupow > 100 AND ostatnieZakupy >= ''2022-01-01''"]'::jsonb, 2, NULL, 'cke', NULL, false, false, '["EE.09 styczen 2024","EE.09 styczen 2025","EE.09 styczen 2026"]'::jsonb);
