insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c3d301b8d389b', 'bazy', 'W tabeli mieszkancy zapisane są osoby z całej Polski. Aby policzyć ile różnych miast występuje w danych tabeli należy zapisać kwerendę', '["SELECT COUNT(miasto) FROM mieszkancy;","SELECT DISTINCT miasto FROM mieszkancy;","SELECT COUNT(DISTINCT miasto) FROM mieszkancy;","SELECT COUNT(miasto) FROM mieszkancy DISTINCT;"]'::jsonb, 2, NULL, 'cke', NULL, false, false, '["EE.09 styczen 2024","EE.09 styczen 2025","EE.09 styczen 2026"]'::jsonb);
