insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c3cc305ba80c1', 'bazy', 'Z przedstawionych tabel Klienci (id, Uslugi_id FK, imie, nazwisko) i Uslugi (id, nazwa, cena) należy wybrać jedynie imiona klientów oraz odpowiadające im nazwy usług, które są droższe niż 10 zł. Kwerenda wybierająca te dane ma postać', '["SELECT imie, nazwa FROM klienci, uslugi WHERE cena < 10;","SELECT imie, nazwa FROM klienci JOIN uslugi ON uslugi.id = uslugi_id;","SELECT imie, nazwa FROM klienci JOIN uslugi ON uslugi.id = klienci.id;","SELECT imie, nazwa FROM klienci JOIN uslugi ON uslugi.id = uslugi_id WHERE cena > 10;"]'::jsonb, 3, NULL, 'cke', NULL, false, false, '["EE.09 styczen 2024","EE.09 styczen 2025","EE.09 styczen 2026"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c51d830c16190', 'podstawy', 'Jednym z pól tabeli ksiazki jest status czyWypozyczona przyjmujący dwie wartości true lub false. Optymalny typ dla tego pola, to', '["CHAR","DOUBLE","BOOLEAN","VARCHAR(5)"]'::jsonb, 2, NULL, 'cke', NULL, false, false, '["EE.09 styczen 2024","EE.09 styczen 2025","EE.09 styczen 2026"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c6a4cc8149e85', 'bazy', 'Podczas tworzenia formularza wymagane jest umieszczenie kontrolki odwołującej się do kontrolki w innym formularzu. Akcja ta w bazie danych Access jest', '["niemożliwa.","możliwa pod warunkiem, że są to dane liczbowe.","niemożliwa we wszystkich trybach oprócz trybu projektu.","możliwa poprzez ustawienie ścieżki do kontrolki we właściwości „Źródło kontrolki”."]'::jsonb, 3, NULL, 'cke', NULL, false, false, '["EE.09 styczen 2024","EE.09 styczen 2025","EE.09 styczen 2026"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cb1b2544719e3', 'bazy', 'W tabeli zadania istnieje pole tekstowe status. Aby usunąć te zadania, których statusem jest ‘zamknięte’ należy zastosować kwerendę', '["DELETE FROM zadania;","TRUNCATE TABLE zadania;","DELETE FROM zadania WHERE status = ''zamknięte'';","TRUNCATE TABLE zadania WHERE status = ''zamknięte'';"]'::jsonb, 2, NULL, 'cke', NULL, false, false, '["EE.09 styczen 2024","EE.09 styczen 2025","EE.09 styczen 2026"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c38162f3caee4', 'bazy', 'GRANT SELECT, INSERT ON baza1.mojaTabela TO ''Jacek''@''localhost''; Po wydaniu polecenia użytkownik Jacek będzie mógł', '["usuwać tabelę i tworzyć nową.","usuwać dane z tabeli i przeglądać dane.","zmieniać strukturę tabeli i wstawiać nowe dane.","przeglądać dane w tabeli i wstawiać nowe dane."]'::jsonb, 3, NULL, 'cke', NULL, false, false, '["EE.09 styczen 2024","EE.09 styczen 2025","EE.09 styczen 2026"]'::jsonb);
