insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c7cd7ed48d21e', 'strony', 'Która z reguł dotyczących stosowania semantycznych znaczników sekcji języka HTML 5 jest prawdziwa?', '["Znacznik <aside> jest stosowany dla głównej treści strony.","Znacznik <nav> jest charakterystyczny dla części <article>.","Znacznik <main> może być zastosowany tylko raz w dokumencie.","Znacznik <footer> powinien być zastosowany na górze strony, a <header> na jej dole."]'::jsonb, 2, NULL, 'cke', NULL, false, false, '["EE.09 styczen 2024","EE.09 styczen 2025","EE.09 styczen 2026"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cf65d3d948826', 'strony', '<title>Strona o psach</title> Co można powiedzieć o przedstawionym zapisie języka HTML 5?', '["Pojawi się na karcie dokumentu w przeglądarce.","Zostanie zapisany w treści strony, na samej górze.","Jest opcjonalny dla języka HTML 5 i nie musi wystąpić w dokumencie.","Jest jedynie informacją dla robotów wyszukiwarek i nie jest wyświetlany przez przeglądarkę."]'::jsonb, 0, NULL, 'cke', NULL, false, false, '["EE.09 styczen 2024","EE.09 styczen 2025","EE.09 styczen 2026"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c38ae6c77bb37', 'strony', 'Fragment menu <a...>Rozdział 2</a> Fragment dalej w dokumencie <h1 id="r2" name="sekcja2" class="rozdzial2">Rozdział 2<h1> Na podstawie fragmentu dokumentu HTML, określ co należy wpisać w miejsce kropek w odnośniku w menu, aby przenosił on do rozdziału 2.', '["href = \"r2\"","href = \"#r2\"","href = \"sekcja2\"","href = \"#sekcja2\""]'::jsonb, 1, NULL, 'cke', NULL, false, false, '["EE.09 styczen 2024","EE.09 styczen 2025","EE.09 styczen 2026"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('c5d7a665ba76b', 'strony', 'Zakładając, że żadne style CSS nie zostały zdefiniowane, przedstawiony efekt (Tytuł, pod nim wcięte "Znaczniki języka HTML", Autor, wcięte "Ewa Konieczna", Słowa kluczowe, wcięte "witryny internetowe, HTML") zostanie uzyskany przy pomocy', '["<ul>\n  <li>Tytuł</li>\n  <li>Znaczniki języka HTML</li>\n  <li>Autor</li>\n  <li>Ewa Konieczna</li>\n  <li>Słowa kluczowe</li>\n  <li>witryny internetowe, HTML</li>\n</ul>","<dl>\n  <dt>Tytuł</dt>\n  <dd>Znaczniki języka HTML</dd>\n  <dt>Autor</dt>\n  <dd>Ewa Konieczna</dd>\n  <dt>Słowa kluczowe</dt>\n  <dd>witryny internetowe, HTML</dd>\n</dl>","<ol>\n  <li>Tytuł</li>\n  <dl>Znaczniki języka HTML</dl>\n  <li>Autor</li>\n  <dl>Ewa Konieczna</dl>\n  <li>Słowa kluczowe</li>\n  <dl>witryny internetowe, HTML</dl>\n</ol>","<table>\n  <tr>Tytuł</tr>\n  <td>Znaczniki języka HTML</td>\n  <tr>Autor</tr>\n  <td>Ewa Konieczna</td>\n  <tr>Słowa kluczowe</tr>\n  <td>witryny internetowe, HTML</td>\n</table>"]'::jsonb, 1, NULL, 'cke', '/q/c5d7a665ba76b-f.webp', false, false, '["EE.09 styczen 2024","EE.09 styczen 2025","EE.09 styczen 2026"]'::jsonb);
insert into public.questions (id, category, text, answers, correct, explanation, source, image, image_answers, ocr, sources) values ('cae2f49adcd8d', 'strony', 'Wskaż styl CSS, za pomocą którego uzyskano przedstawiony efekt (kwadratowe zdjęcie zostało wyświetlone jako koło).', '["img {\n  width: 100px;\n  border-radius:10%;\n}","img {\n  width: 100px;\n  border-radius:50px;\n}","img {\n  width: 100px;\n  border:50% green;\n}","img {\n  width: 100px;\n  shape:circle;\n}"]'::jsonb, 1, NULL, 'cke', '/q/cae2f49adcd8d-f.webp', false, false, '["EE.09 styczen 2024","EE.09 styczen 2025","EE.09 styczen 2026"]'::jsonb);
